%[text] # ot rable odClamped beam example
%[text] Worked example of the clamped beam found in [Evaluating applied force reduced-order models: validation](https://doi.org/10.1007/s11071-026-12844-7)
%[text] ![](text:image:2e6e)
%[text] Make sure '`AFR_tool.prj`' is open
%%
%[text] The logging and visualisation levels determine how much is outputted to the console and as graphical representations respectively. The higher the number, the more verbose the output.
clear
set_script_wd(); %sets working directory to "...\clamped_beam" %[output:2f69027d]
set_logging_level(3)
set_visualisation_level(3)
%%
%[text] ## {1}-ROM
%[text] ### Static dataset 
%[text] To create the {1}-ROM, the system (as defined in [.\\geometry\\clamped\_beam\\clamped\_beam.inp](file:.\\geometry\\clamped_beam\\clamped_beam.inp)), ROM limit and reduction basis needs to be specified.
%[text] Additionally the tangent stiffness at each loadcase is requested for later validation.
%--------- System Settings ---------%
system_name = "clamped_beam";
energy_limit = 0.01; %(J)
reduction_basis = 1;
%-----------------------------------%

%--------- Static Solver Settings ---------%
Static_Opts.additional_data = "stiffness";
Static_Opts.max_parallel_jobs =  1;
%------------------------------------------%

Model = Dynamic_System(system_name,energy_limit,reduction_basis,"static_opts",Static_Opts); %[output:92c2981c] %[output:2249e788] %[output:5f36b794]
Static_Data = Static_Dataset(Model); %[output:01274de8] %[output:4c331674] %[output:158559da] %[output:1ebbdf9f]
Static_Data.save_data; %[output:1bb057a3]
%%
%[text] ### Periodic orbits
rom_name = "clamped_beam_1";
Dyn_Data = initalise_dynamic_data(rom_name); %[output:646fce99]
Dyn_Data = Dyn_Data.remove_solution("all");
%[text] The `Continuation_Opts` map to the corresponding continuation and collocation settings in COCO.
%--------- Continuation Settings ---------%
Continuation_Opts.initial_inc = 5e-2;
Continuation_Opts.max_inc = 5e-2;
Continuation_Opts.min_inc = 5e-3;

Continuation_Opts.forward_steps = 200;
Continuation_Opts.backward_steps = 0;
Continuation_Opts.collocation_degree = 6;
Continuation_Opts.min_discretisation_num = 20;
%-----------------------------------------%

Dyn_Data = Dyn_Data.add_backbone(1,"opts",Continuation_Opts); %[output:494f384c]
%%
%[text] #### Validation
set_visualisation_level(1)
compare_validation("clamped_beam_1","validation error",1,1:10); %[output:946ae271] %[output:5f4d93c4]
%%
%[text] #### Locating the internal resonance
%[text] In order predict the location of the internal resonance precisely, a far denser backbone curve needs to be validated.
Continuation_Opts.initial_inc = 2e-3;
Continuation_Opts.min_inc = 1e-3;
Continuation_Opts.max_inc = 2e-3;
Continuation_Opts.forward_steps = 100;
Continuation_Opts.backward_steps = 100;
Continuation_Opts.collocation_degree = 6;
Continuation_Opts.min_discretisation_num = 20;
%-----------------------------------------
Dyn_Data = Dyn_Data.add_orbits(1,[7,11],"opts",Continuation_Opts); %adds orbits between orbit ID 7 and 11 %[output:05363af2]
compare_validation(Dyn_Data,"validation error","last",[3,6]); %[output:0334c9be] %[output:5ebab5f1]
%--
Dyn_Data = validate_solution(Dyn_Data,2,3); %only last validation analysis is saved %[output:9659fa0b]
compare_solutions("amplitude",Dyn_Data,2,"validation",1) %[output:958abb9a] %[output:694b201d] %[output:3f1c142b]
%%
%[text] ## {1,3}-ROM
%[text] ### Static dataset
%[text] The original dataset can be re-used when creating the two-mode ROM
set_visualisation_level(3)

%--------- System Settings ---------%
added_mode = 3;
%-----------------------------------%
Static_Data = load_static_data("clamped_beam_1") %[output:338ec580]

Static_Data = Static_Data.update_model(added_mode); %[output:6d102aaa] %[output:6c6d3035] %[output:79227812]
Static_Data = Static_Data.create_dataset; %[output:82273f35]
Static_Data.save_data; %[output:377d75e0]
%%
%[text] ### Periodic orbits
%----- Initalise Dynamic Data -----%
rom_name = "clamped_beam_13";
Dyn_Data = initalise_dynamic_data(rom_name); %[output:4f18f699]
Dyn_Data = Dyn_Data.remove_solution("all");
%----------------------------------%

Continuation_Opts.initial_inc = 2e-2;
Continuation_Opts.max_inc = 2e-2;
Continuation_Opts.min_inc = 5e-3;

Continuation_Opts.forward_steps = 200;
Continuation_Opts.backward_steps = 0;
Continuation_Opts.collocation_degree = 6;
Continuation_Opts.initial_discretisation_num = 20;
Continuation_Opts.min_discretisation_num = 20;
%-----------------------------------------%
Dyn_Data = Dyn_Data.add_backbone(1,"opts",Continuation_Opts); %[output:98f63425]
%%
%[text] #### Validation
set_visualisation_level(1)
compare_validation("clamped_beam_13","validation error",1,1:10); %[output:87397729] %[output:2ea47e3b] %[output:84f9de69] %[output:1f47e182] %[output:2332828e] %[output:4edbc458] %[output:36a6a106] %[output:7e9622a7] %[output:2c883851] %[output:6423381e] %[output:6159f154] %[output:83f368a3] %[output:22480612] %[output:91a2c2b2] %[output:9dde3955] %[output:66dd6953] %[output:8f915462] %[output:5357e0c1] %[output:10388d75] %[output:120897c2] %[output:66bc22f7] %[output:16fa58ea] %[output:3998b21f] %[output:87f0ee14] %[output:33188ad8] %[output:3a3f75be] %[output:9486ce6a] %[output:058268c4] %[output:6908da1e] %[output:39bc0758] %[output:715915dc] %[output:99eadf96] %[output:06deb183] %[output:7862b14e] %[output:4216c588] %[output:41e81d93] %[output:58c0626f] %[output:2d4ee93f] %[output:08c1d4d3] %[output:9f6ced91] %[output:0476fbc9] %[output:59ceff97] %[output:182a5369] %[output:458fc789] %[output:4d0fc778] %[output:5b2d8382] %[output:17667bea] %[output:9db5d057] %[output:73a22bc3] %[output:5fe205c2] %[output:6d2ba756] %[output:13fdf469] %[output:9c7aced5] %[output:13109840] %[output:26562eff] %[output:20b8adef] %[output:66bd02a8] %[output:49b9329e] %[output:08b100bf] %[output:01585995] %[output:226b01de] %[output:4caad5b0] %[output:1e5813ab] %[output:1ad1f948] %[output:5982c5c2] %[output:1cf9100e] %[output:860caa18] %[output:8d896a53] %[output:0fb2044a] %[output:836252cb] %[output:5126db5f] %[output:8aa2dba6] %[output:2a8a8c5c] %[output:1158aaeb] %[output:57bc09c8] %[output:532c2b5f] %[output:9cccc9af] %[output:17651ab4] %[output:9b99ed69] %[output:43678fc9] %[output:1f03c618] %[output:8755595e] %[output:226c7bb1] %[output:225663b4] %[output:2e579b19] %[output:69dead95] %[output:5dff7c38] %[output:297959da] %[output:00f8e0fa] %[output:87a54db6] %[output:3131cc5d] %[output:71fdd16b] %[output:7de68089] %[output:39aa1862] %[output:78f7615b] %[output:1b3f1372] %[output:8f7f3461] %[output:45a3f575] %[output:8d29e7b4] %[output:68a40243] %[output:1831dd0a] %[output:767c812